Definition rs_pre (ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
    (bs stb ioc implb MB tgt tn ec spa lo shi ff fp : Z) (LB : list block) (LF : list fframe) (S : statev) (ds junk : list byte) (E : ecv)
    (m mx : mem) : Prop :=
  exists (t0j ja jb t1j hj h8 h1 hk sh8 : list byte) (gap : list cell),
     rw_cells asegs mx spa [CB 16 t0j; CB 8 ja; CB 8 jb; CB 16 t1j; C8 (wz ff)]
  /\ rw_cells asegs mx (spa + 56) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -160 - spa
  /\ (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176)
  /\ rw_cells asegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
  /\ rw_cells asegs mx ff [CB 32 hj; CB 8 h8; CB 1 h1; CB 15 hk; C8 (wz fp)]
  /\ rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 8 sh8]
  /\ rw_cells asegs mx fp [C1 (b8 1)]
  /\ stk asegs mx lo spa /\ mem_inv asegs mx
  /\ as_RFS H ((0, ff, fp) :: LF) mx /\ fresh_frame H LF 0 ff fp /\ ACONST mx /\ stack0 mx lo shi /\ as_RFS H LF m
  /\ munch (rs_W H lo sp stb ec tgt tn ff fp) m mx /\ wmono asegs m mx
  /\ AStateBlock LB mx stb ioc implb S ds /\ st_lk S = 0 /\ (ds = [] -> st_code S = STREAM_EOF)
  /\ st_nread S + 1 < 2^63 /\ st_nread_bytes S + zlength ds < 2^63
  /\ ro_cells asegs mx bs [C8 (wz (stb + O_SPC_STORAGE))] /\ bs mod 8 = 0 /\ aplace bs 8 /\ fsobj H LF bs 8 /\ accessible mx bs 8
  /\ (bs + 8 <= lo \/ bv_unsigned sp <= bs)
  /\ ro_cells asegs mx MB [C8 (wz tgt); C8 (wz tn)] /\ MB mod 8 = 0 /\ aplace MB 16 /\ fsobj H LF MB 16 /\ accessible mx MB 16
  /\ (MB + 16 <= lo \/ bv_unsigned sp <= MB)
  /\ rw_cells asegs mx tgt [CB (Z.to_nat tn) junk] /\ 1 <= tn < 2^40 /\ aapp tgt tn /\ tgt + tn <= aceil /\ fsobj H LF tgt tn
  /\ accessible mx tgt tn /\ shvis mx tgt (tgt + tn)
  /\ rw_cells asegs mx ec (ErrCodeCells E) /\ ec mod 8 = 0 /\ aapp ec 24 /\ fsobj H LF ec 24 /\ accessible mx ec 24
  /\ (ec + 24 <= lo \/ bv_unsigned sp <= ec)
  /\ AXStatics2 mx /\ AMiscVt48 mx
  /\ fsobj H LF stb SZ_SPCI_STATE
  /\ (st_fb S <> FB_empty -> fsobj H LF (fb_begin (st_fb S)) (fb_cap (st_fb S)) /\ shvis mx (fb_begin (st_fb S)) (fb_end (st_fb S)))
  /\ (tgt + tn <= stb \/ stb + SZ_SPCI_STATE <= tgt)
  /\ (st_fb S <> FB_empty -> tgt + tn <= fb_begin (st_fb S) \/ fb_end (st_fb S) <= tgt)
  /\ (tgt + tn <= ec \/ ec + 24 <= tgt) /\ (tgt + tn <= MB \/ MB + 16 <= tgt)
  /\ (ec + 24 <= stb \/ stb + SZ_SPCI_STATE <= ec) /\ (ec + 24 <= MB \/ MB + 16 <= ec) /\ (ec + 24 <= bs \/ bs + 8 <= ec)
  /\ (bs + 8 <= stb \/ stb + SZ_SPCI_STATE <= bs) /\ (MB + 16 <= stb \/ stb + SZ_SPCI_STATE <= MB) /\ (tgt + tn <= bs \/ bs + 8 <= tgt)
  /\ (st_fb S <> FB_empty -> ec + 24 <= fb_begin (st_fb S) \/ fb_end (st_fb S) <= ec)
  /\ (st_fb S <> FB_empty -> fb_end (st_fb S) <= stb \/ stb + SZ_SPCI_STATE <= fb_begin (st_fb S))
  /\ lo + AREADSOME_STACK <= bv_unsigned sp /\ aceil <= lo /\ bv_unsigned ra mod 2 = 0.
